<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$data=[];foreach($bouquets as $b){$b['category_ids']=$map[(int)$b['id']]??[];$data[]=$b;}?>
<div x-data="bouquetPage(<?=htmlspecialchars(json_encode($data,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT),ENT_QUOTES)?>)" class="space-y-6"><div class="flex justify-between"><div><h1 class="text-3xl font-bold">Bouquets</h1><p class="text-slate-400">Agrupa canales, películas y series; después asigna estos bouquets a los Packages.</p></div><button @click="create()" class="bg-cyan-600 px-4 py-2 rounded">Crear bouquet</button></div><section class="grid md:grid-cols-2 xl:grid-cols-3 gap-4"><?php foreach($bouquets as $b):?><article class="bg-slate-900 border border-slate-800 rounded-xl p-5"><div class="flex justify-between"><h2 class="text-xl font-bold"><?=$e($b['name'])?></h2><span class="<?=$b['active']?'text-emerald-400':'text-amber-400'?>"><?=$b['active']?'Activo':'Inactivo'?></span></div><p class="text-sm text-slate-400 mt-1"><?=$e($b['description']??'')?></p><div class="mt-4 text-sm"><?=$e($b['category_names']??'Sin categorías')?></div><div class="grid grid-cols-2 gap-2 mt-4 text-center"><div class="bg-slate-800 p-2 rounded"><strong><?=$b['categories_count']?></strong><div class="text-xs text-slate-500">categorías</div></div><div class="bg-slate-800 p-2 rounded"><strong><?=$b['items_count']?></strong><div class="text-xs text-slate-500">contenidos</div></div></div><div class="flex gap-2 mt-4"><button @click="edit(<?=$b['id']?>)" class="flex-1 bg-indigo-700 py-2 rounded">Editar</button><form method="post" action="/bouquets/toggle"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$b['id']?>"><button class="bg-slate-700 px-4 py-2 rounded"><?=$b['active']?'Desactivar':'Activar'?></button></form></div></article><?php endforeach?></section><div x-show="open" x-cloak style="display:none" class="relative bg-black/75 z-50 grid place-items-center p-4" @click.self="open=false"><form method="post" action="/bouquets" class="bg-slate-900 border border-slate-700 rounded-2xl p-6 max-w-4xl w-full max-h-[90vh] overflow-auto"><?=$csrf->field()?><input type="hidden" name="id" :value="form.id"><h2 class="text-2xl font-bold" x-text="form.id?'Editar bouquet':'Nuevo bouquet'"></h2><div class="grid md:grid-cols-2 gap-3 mt-4"><input required name="name" x-model="form.name" placeholder="Nombre" class="bg-slate-800 p-2 rounded"><input name="description" x-model="form.description" placeholder="Descripción" class="bg-slate-800 p-2 rounded"><label><input type="checkbox" name="active" x-model="form.active"> Activo</label></div><div class="grid md:grid-cols-3 gap-4 mt-5"><?php foreach(['live'=>'Canales','movie'=>'Películas','series'=>'Series'] as $type=>$label):?><fieldset class="bg-slate-800/60 rounded-xl p-4"><legend class="font-bold px-2"><?=$label?></legend><div class="space-y-2 max-h-72 overflow-auto"><?php foreach($categories as $c):if($c['type']!==$type)continue;?><label class="flex gap-2"><input type="checkbox" name="category_ids[]" value="<?=$c['id']?>" :checked="form.category_ids.includes(<?=$c['id']?>)"><span><?=$e($c['name'])?> <small class="text-slate-500"><?=$c['items_count']?></small></span></label><?php endforeach?></div></fieldset><?php endforeach?></div><div class="flex justify-end gap-2 mt-5"><button type="button" @click="open=false" class="bg-slate-700 px-4 py-2 rounded">Cancelar</button><button class="bg-emerald-700 px-4 py-2 rounded">Guardar bouquet</button></div></form></div></div>
<script>function bouquetPage(items){return{items,open:false,form:{},create(){this.form={id:'',name:'',description:'',active:true,category_ids:[]};this.open=true},edit(id){let b=this.items.find(x=>Number(x.id)===id);this.form={...b,active:Boolean(Number(b.active)),category_ids:(b.category_ids||[]).map(Number)};this.open=true}}}</script>
